@_mutmut_mutated(mutants_x__mask_cpf__mutmut)
def _mask_cpf(cpf: str) -> str:
    """Masks first 3 and last 2 digits of a CPF for LGPD compliance."""
    parts = cpf.split("-")
    if len(parts) == 2:
        num_parts = parts[0].split(".")
        if len(num_parts) == 3:
            return f"***.{num_parts[1]}.{num_parts[2]}-**"
    return "***.***.***-**"


